{
  "claims": [
    {
      "quote": "Johnson & Johnson’s most recently completed fiscal year was 2024, ended December 28.",
      "verdict": "wrong"
    },
    {
      "quote": "In FY2024, JNJ reported revenue of $89.84 billion, up 5.7% from $84.98 billion in FY2023, and up from $95.77 billion in FY2022.",
      "verdict": "wrong"
    },
    {
      "quote": "Net earnings were $12.53 billion in FY2024, down from $14.71 billion in FY2023 and $20.88 billion in FY2022, with diluted EPS of about $11.02 in FY2024.",
      "verdict": "wrong"
    },
    {
      "quote": "Adjusted EPS was roughly $11.98.",
      "verdict": "unchecked"
    },
    {
      "quote": "Operating cash flow was about $23.8 billion in FY2024, though free cash flow was lower after capex.",
      "verdict": "wrong"
    },
    {
      "quote": "Operating margin was approximately 24.6% in FY2024, down from prior years; net margin was about 14%.",
      "verdict": "unchecked"
    },
    {
      "quote": "Growth was modest, reflecting fading COVID vaccine revenue.",
      "verdict": "unchecked"
    },
    {
      "quote": "Fiscal 2023 results showed revenue of $84.98 billion, net earnings of $14.71 billion, and EPS of $13.33.",
      "verdict": "wrong"
    },
    {
      "quote": "Fiscal 2022 revenue was $95.77 billion, net earnings $20.88 billion, and EPS $17.79, as COVID-19 vaccine and treatment sales inflated results.",
      "verdict": "wrong"
    }
  ],
  "action": "block"
}
